<?php
 class RequestTest extends PHPUnit_Framework_TestCase { public function testGetMethod() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'GET' )); $req = new \Slim\Http\Request($env); $this->assertEquals('GET', $req->getMethod()); } public function testIsGet() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'GET' )); $req = new \Slim\Http\Request($env); $this->assertTrue($req->isGet()); } public function testIsPost() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'POST', )); $req = new \Slim\Http\Request($env); $this->assertTrue($req->isPost()); } public function testIsPut() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'PUT', )); $req = new \Slim\Http\Request($env); $this->assertTrue($req->isPut()); } public function testIsDelete() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'DELETE', )); $req = new \Slim\Http\Request($env); $this->assertTrue($req->isDelete()); } public function testIsOptions() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'OPTIONS', )); $req = new \Slim\Http\Request($env); $this->assertTrue($req->isOptions()); } public function testIsHead() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'HEAD', )); $req = new \Slim\Http\Request($env); $this->assertTrue($req->isHead()); } public function testIsPatch() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'PATCH', )); $req = new \Slim\Http\Request($env); $this->assertTrue($req->isPatch()); } public function testIsAjaxWithHeader() { $env = \Slim\Environment::mock(array( 'X_REQUESTED_WITH' => 'XMLHttpRequest' )); $req = new \Slim\Http\Request($env); $this->assertTrue($req->isAjax()); $this->assertTrue($req->isXhr()); } public function testIsAjaxWithQueryParameter() { $env = \Slim\Environment::mock(array( 'QUERY_STRING' => 'isajax=1', )); $req = new \Slim\Http\Request($env); $this->assertTrue($req->isAjax()); $this->assertTrue($req->isXhr()); } public function testIsAjaxWithoutHeaderOrQueryParameter() { $env = \Slim\Environment::mock(); $req = new \Slim\Http\Request($env); $this->assertFalse($req->isAjax()); $this->assertFalse($req->isXhr()); } public function testIsAjaxWithMisspelledHeader() { $env = \Slim\Environment::mock(array( 'X_REQUESTED_WITH' => 'foo' )); $req = new \Slim\Http\Request($env); $this->assertFalse($req->isAjax()); $this->assertFalse($req->isXhr()); } public function testParamsFromQueryString() { $env = \Slim\Environment::mock(array( 'QUERY_STRING' => 'one=1&two=2&three=3' )); $req = new \Slim\Http\Request($env); $this->assertEquals(3, count($req->params())); $this->assertEquals('1', $req->params('one')); $this->assertNull($req->params('foo')); $this->assertEquals(1, $req->params('foo', 1)); } public function testParamsFromRequestBody() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'POST', 'QUERY_STRING' => 'one=1&two=2&three=3', 'slim.input' => 'foo=bar&abc=123', 'CONTENT_TYPE' => 'application/x-www-form-urlencoded', 'CONTENT_LENGTH' => 15 )); $req = new \Slim\Http\Request($env); $this->assertEquals(5, count($req->params())); $this->assertEquals('bar', $req->params('foo')); } public function testGet() { $env = \Slim\Environment::mock(array( 'QUERY_STRING' => 'one=1&two=2&three=3' )); $req = new \Slim\Http\Request($env); $this->assertEquals(3, count($req->get())); $this->assertEquals('1', $req->get('one')); $this->assertNull($req->get('foo')); $this->assertFalse($req->get('foo', false)); } public function testGetWithoutMultibyte() { $env = \Slim\Environment::mock(array( 'QUERY_STRING' => 'one=1&two=2&three=3', 'slim.tests.ignore_multibyte' => true )); $req = new \Slim\Http\Request($env); $this->assertEquals(3, count($req->get())); $this->assertEquals('1', $req->get('one')); $this->assertNull($req->get('foo')); $this->assertFalse($req->get('foo', false)); } public function testPost() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'POST', 'slim.input' => 'foo=bar&abc=123', 'CONTENT_TYPE' => 'application/x-www-form-urlencoded', 'CONTENT_LENGTH' => 15 )); $req = new \Slim\Http\Request($env); $this->assertEquals(2, count($req->post())); $this->assertEquals('bar', $req->post('foo')); $this->assertNull($req->post('xyz')); $this->assertFalse($req->post('xyz', false)); } public function testPostWithoutMultibyte() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'POST', 'slim.input' => 'foo=bar&abc=123', 'CONTENT_TYPE' => 'application/x-www-form-urlencoded', 'CONTENT_LENGTH' => 15, 'slim.tests.ignore_multibyte' => true )); $req = new \Slim\Http\Request($env); $this->assertEquals(2, count($req->post())); $this->assertEquals('bar', $req->post('foo')); $this->assertNull($req->post('xyz')); $this->assertFalse($req->post('xyz', false)); } public function testPostWithoutInput() { $this->setExpectedException('RuntimeException'); $env = \Slim\Environment::mock(); unset($env['slim.input']); $req = new \Slim\Http\Request($env); $req->post('foo'); } public function testPostWithMultipartRequest() { $_POST = array('foo' => 'bar'); $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'POST', 'slim.input' => '', 'CONTENT_TYPE' => 'multipart/form-data', 'CONTENT_LENGTH' => 0 )); $req = new \Slim\Http\Request($env); $this->assertEquals(1, count($req->post())); $this->assertEquals('bar', $req->post('foo')); $this->assertNull($req->post('xyz')); } public function testPut() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'PUT', 'slim.input' => 'foo=bar&abc=123', 'CONTENT_TYPE' => 'application/x-www-form-urlencoded', 'CONTENT_LENGTH' => 15 )); $req = new \Slim\Http\Request($env); $this->assertEquals(2, count($req->put())); $this->assertEquals('bar', $req->put('foo')); $this->assertEquals('bar', $req->params('foo')); $this->assertNull($req->put('xyz')); $this->assertFalse($req->put('xyz', false)); } public function testPatch() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'PATCH', 'slim.input' => 'foo=bar&abc=123', 'CONTENT_TYPE' => 'application/x-www-form-urlencoded', 'CONTENT_LENGTH' => 15 )); $req = new \Slim\Http\Request($env); $this->assertEquals(2, count($req->patch())); $this->assertEquals('bar', $req->patch('foo')); $this->assertEquals('bar', $req->params('foo')); $this->assertNull($req->patch('xyz')); $this->assertFalse($req->patch('xyz', false)); } public function testDelete() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'DELETE', 'slim.input' => 'foo=bar&abc=123', 'CONTENT_TYPE' => 'application/x-www-form-urlencoded', 'CONTENT_LENGTH' => 15 )); $req = new \Slim\Http\Request($env); $this->assertEquals(2, count($req->delete())); $this->assertEquals('bar', $req->delete('foo')); $this->assertEquals('bar', $req->params('foo')); $this->assertNull($req->delete('xyz')); $this->assertFalse($req->delete('xyz', false)); } public function testCookies() { $env = \Slim\Environment::mock(array( 'HTTP_COOKIE' => 'foo=bar; abc=123' )); $req = new \Slim\Http\Request($env); $this->assertEquals(2, count($req->cookies())); $this->assertEquals('bar', $req->cookies('foo')); $this->assertNull($req->cookies('xyz')); } public function testIsFormDataContentFormUrlencoded() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'PUT', 'slim.input' => '', 'CONTENT_TYPE' => 'application/x-www-form-urlencoded' )); $req = new \Slim\Http\Request($env); $this->assertTrue($req->isFormData()); } public function testIsFormDataPostContentUnknown() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'POST', 'slim.input' => '', )); $req = new \Slim\Http\Request($env); $this->assertTrue($req->isFormData()); } public function testIsFormDataPostContentUnknownWithMethodOverride() { $env = \Slim\Environment::mock(array( 'REQUEST_METHOD' => 'PUT', )); $env['slim.method_override.original_method'] = 'POST'; $req = new \Slim\Http\Request($env); $this->assertTrue($req->isPut()); $this->assertTrue($req->isFormData()); } public function testIsNotFormData() { $env = \Slim\Environment::mock(array( 'slim.input' => '', 'CONTENT_TYPE' => 'application/json' )); $req = new \Slim\Http\Request($env); $this->assertFalse($req->isFormData()); } public function testHeaders() { $env = \Slim\Environment::mock(array( 'HTTP_ACCEPT_ENCODING' => 'gzip' )); $req = new \Slim\Http\Request($env); $headers = $req->headers(); $this->assertInstanceOf('\Slim\Http\Headers', $headers); $this->assertEquals('gzip', $req->headers('HTTP_ACCEPT_ENCODING')); $this->assertEquals('gzip', $req->headers('HTTP-ACCEPT-ENCODING')); $this->assertEquals('gzip', $req->headers('http_accept_encoding')); $this->assertEquals('gzip', $req->headers('http-accept-encoding')); $this->assertEquals('gzip', $req->headers('ACCEPT_ENCODING')); $this->assertEquals('gzip', $req->headers('ACCEPT-ENCODING')); $this->assertEquals('gzip', $req->headers('accept_encoding')); $this->assertEquals('gzip', $req->headers('accept-encoding')); $this->assertNull($req->headers('foo')); } public function testHeaderRemovesHttpPrefix() { $env = \Slim\Environment::mock(array( 'X_HTTP_METHOD_OVERRIDE' => 'PUT', 'CONTENT_TYPE' => 'application/json' )); $req = new \Slim\Http\Request($env); $this->assertEquals('PUT', $req->headers('X_HTTP_METHOD_OVERRIDE')); $this->assertNull($req->headers('X_METHOD_OVERRIDE')); $this->assertEquals('application/json', $req->headers('HTTP_CONTENT_TYPE')); } public function testGetBodyWhenExists() { $env = \Slim\Environment::mock(array( 'slim.input' => 'foo=bar&abc=123', 'CONTENT_TYPE' => 'application/x-www-form-urlencoded', 'CONTENT_LENGTH' => 15 )); $req = new \Slim\Http\Request($env); $this->assertEquals('foo=bar&abc=123', $req->getBody()); } public function testGetBodyWhenNotExists() { $env = \Slim\Environment::mock(); $req = new \Slim\Http\Request($env); $this->assertEquals('', $req->getBody()); } public function testGetContentTypeWhenExists() { $env = \Slim\Environment::mock(array( 'slim.input' => '', 'CONTENT_TYPE' => 'application/json; charset=ISO-8859-4' )); $req = new \Slim\Http\Request($env); $this->assertEquals('application/json; charset=ISO-8859-4', $req->getContentType()); } public function testGetContentTypeForBuiltInServer() { $env = \Slim\Environment::mock(array( 'slim.input' => '', 'HTTP_CONTENT_TYPE' => 'application/json; charset=ISO-8859-4' )); $req = new \Slim\Http\Request($env); $this->assertEquals('application/json; charset=ISO-8859-4', $req->getContentType()); } public function testGetContentTypeWhenNotExists() { $env = \Slim\Environment::mock(); $req = new \Slim\Http\Request($env); $this->assertNull($req->getContentType()); } public function testGetContentTypeWithBuiltInServer() { $env = \Slim\Environment::mock(array( 'slim.input' => '', 'HTTP_CONTENT_TYPE' => 'application/json; charset=ISO-8859-4' )); $req = new \Slim\Http\Request($env); $this->assertEquals('application/json; charset=ISO-8859-4', $req->getContentType()); } public function testGetMediaTypeWhenExists() { $env = \Slim\Environment::mock(array( 'CONTENT_TYPE' => 'application/json;charset=utf-8' )); $req = new \Slim\Http\Request($env); $this->assertEquals('application/json', $req->getMediaType()); } public function testGetMediaTypeWhenNotExists() { $env = \Slim\Environment::mock(); $req = new \Slim\Http\Request($env); $this->assertNull($req->getMediaType()); } public function testGetMediaTypeWhenNoParamsExist() { $env = \Slim\Environment::mock(array( 'slim.input' => '', 'CONTENT_TYPE' => 'application/json' )); $req = new \Slim\Http\Request($env); $this->assertEquals('application/json', $req->getMediaType()); } public function testGetMediaTypeParams() { $env = \Slim\Environment::mock(array( 'CONTENT_TYPE' => 'application/json; charset=ISO-8859-4' )); $req = new \Slim\Http\Request($env); $params = $req->getMediaTypeParams(); $this->assertEquals(1, count($params)); $this->assertArrayHasKey('charset', $params); $this->assertEquals('ISO-8859-4', $params['charset']); } public function testGetMediaTypeParamsWhenNotExists() { $env = \Slim\Environment::mock(); $req = new \Slim\Http\Request($env); $params = $req->getMediaTypeParams(); $this->assertTrue(is_array($params)); $this->assertEquals(0, count($params)); } public function testGetContentCharset() { $env = \Slim\Environment::mock(array( 'slim.input' => '', 'CONTENT_TYPE' => 'application/json; charset=ISO-8859-4' )); $req = new \Slim\Http\Request($env); $this->assertEquals('ISO-8859-4', $req->getContentCharset()); } public function testGetContentCharsetWhenNotExists() { $env = \Slim\Environment::mock(array( 'slim.input' => '', 'CONTENT_TYPE' => 'application/json' )); $req = new \Slim\Http\Request($env); $this->assertNull($req->getContentCharset()); } public function testGetContentLength() { $env = \Slim\Environment::mock(array( 'slim.input' => 'foo=bar&abc=123', 'CONTENT_TYPE' => 'application/x-www-form-urlencoded', 'CONTENT_LENGTH' => 15 )); $req = new \Slim\Http\Request($env); $this->assertEquals(15, $req->getContentLength()); } public function testGetContentLengthWhenNotExists() { $env = \Slim\Environment::mock(array( 'slim.input' => '', )); $req = new \Slim\Http\Request($env); $this->assertEquals(0, $req->getContentLength()); } public function testGetHost() { $env = \Slim\Environment::mock(array( 'SERVER_NAME' => 'slim', 'HTTP_HOST' => 'slimframework.com' )); $req = new \Slim\Http\Request($env); $this->assertEquals('slimframework.com', $req->getHost()); } public function testGetHostAndStripPort() { $env = \Slim\Environment::mock(array( 'SERVER_NAME' => 'slim', 'HTTP_HOST' => 'slimframework.com:80' )); $req = new \Slim\Http\Request($env); $this->assertEquals('slimframework.com', $req->getHost()); } public function testGetHostWhenNotExists() { $env = \Slim\Environment::mock(array( 'SERVER_NAME' => 'slim', 'HTTP_HOST' => 'slimframework.com' )); unset($env['HTTP_HOST']); $req = new \Slim\Http\Request($env); $this->assertEquals('slim', $req->getHost()); } public function testGetHostWithPort() { $env = \Slim\Environment::mock(array( 'HTTP_HOST' => 'slimframework.com', 'SERVER_NAME' => 'slim', 'SERVER_PORT' => 80, 'slim.url_scheme' => 'http' )); $req = new \Slim\Http\Request($env); $this->assertEquals('slimframework.com:80', $req->getHostWithPort()); } public function testGetHostDoesntDuplicatePort() { $env = \Slim\Environment::mock(array( 'HTTP_HOST' => 'slimframework.com:80', 'SERVER_NAME' => 'slim', 'SERVER_PORT' => 80, 'slim.url_scheme' => 'http' )); $req = new \Slim\Http\Request($env); $this->assertEquals('slimframework.com:80', $req->getHostWithPort()); } public function testGetPort() { $env = \Slim\Environment::mock(array( 'SERVER_PORT' => 80 )); $req = new \Slim\Http\Request($env); $this->assertTrue(is_integer($req->getPort())); $this->assertEquals(80, $req->getPort()); } public function testGetSchemeIfHttp() { $env = \Slim\Environment::mock(array( 'slim.url_scheme' => 'http' )); $req = new \Slim\Http\Request($env); $this->assertEquals('http', $req->getScheme()); } public function testGetSchemeIfHttps() { $env = \Slim\Environment::mock(array( 'slim.url_scheme' => 'https', )); $req = new \Slim\Http\Request($env); $this->assertEquals('https', $req->getScheme()); } public function testAppPathsInSubdirectoryWithoutHtaccess() { $env = \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo/index.php', 'PATH_INFO' => '/bar/xyz', )); $req = new \Slim\Http\Request($env); $this->assertEquals('/foo/index.php', $req->getScriptName()); $this->assertEquals('/foo/index.php', $req->getRootUri()); $this->assertEquals('/foo/index.php/bar/xyz', $req->getPath()); $this->assertEquals('/bar/xyz', $req->getPathInfo()); $this->assertEquals('/bar/xyz', $req->getResourceUri()); } public function testAppPathsInSubdirectoryWithHtaccess() { $env = \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/foo', 'PATH_INFO' => '/bar/xyz', )); $req = new \Slim\Http\Request($env); $this->assertEquals('/foo', $req->getScriptName()); $this->assertEquals('/foo', $req->getRootUri()); $this->assertEquals('/foo/bar/xyz', $req->getPath()); $this->assertEquals('/bar/xyz', $req->getPathInfo()); $this->assertEquals('/bar/xyz', $req->getResourceUri()); } public function testAppPathsInRootDirectoryWithoutHtaccess() { $env = \Slim\Environment::mock(array( 'SCRIPT_NAME' => '/index.php', 'PATH_INFO' => '/bar/xyz', )); $req = new \Slim\Http\Request($env); $this->assertEquals('/index.php', $req->getScriptName()); $this->assertEquals('/index.php', $req->getRootUri()); $this->assertEquals('/index.php/bar/xyz', $req->getPath()); $this->assertEquals('/bar/xyz', $req->getPathInfo()); $this->assertEquals('/bar/xyz', $req->getResourceUri()); } public function testAppPathsInRootDirectoryWithHtaccess() { $env = \Slim\Environment::mock(array( 'SCRIPT_NAME' => '', 'PATH_INFO' => '/bar/xyz', )); $req = new \Slim\Http\Request($env); $this->assertEquals('', $req->getScriptName()); $this->assertEquals('', $req->getRootUri()); $this->assertEquals('/bar/xyz', $req->getPath()); $this->assertEquals('/bar/xyz', $req->getPathInfo()); $this->assertEquals('/bar/xyz', $req->getResourceUri()); } public function testGetUrl() { $env = \Slim\Environment::mock(array( 'HTTP_HOST' => 'slimframework.com', 'SERVER_NAME' => 'slim', 'SERVER_PORT' => 80, 'slim.url_scheme' => 'http' )); $req = new \Slim\Http\Request($env); $this->assertEquals('http://slimframework.com', $req->getUrl()); } public function testGetUrlWithCustomPort() { $env = \Slim\Environment::mock(array( 'HTTP_HOST' => 'slimframework.com', 'SERVER_NAME' => 'slim', 'SERVER_PORT' => 8080, 'slim.url_scheme' => 'http' )); $req = new \Slim\Http\Request($env); $this->assertEquals('http://slimframework.com:8080', $req->getUrl()); } public function testGetUrlWithHttps() { $env = \Slim\Environment::mock(array( 'HTTP_HOST' => 'slimframework.com', 'SERVER_NAME' => 'slim', 'SERVER_PORT' => 443, 'slim.url_scheme' => 'https' )); $req = new \Slim\Http\Request($env); $this->assertEquals('https://slimframework.com', $req->getUrl()); } public function testGetIp(array $server, $expected) { $env = \Slim\Environment::mock($server); $req = new \Slim\Http\Request($env); $this->assertEquals($expected, $req->getIp()); } public function dataTestIp() { return array( array(array('REMOTE_ADDR' => '127.0.0.1'), '127.0.0.1'), array(array('REMOTE_ADDR' => '127.0.0.1', 'CLIENT_IP' => '127.0.0.2'), '127.0.0.2'), array(array('REMOTE_ADDR' => '127.0.0.1', 'CLIENT_IP' => '127.0.0.2', 'X_FORWARDED_FOR' => '127.0.0.3'), '127.0.0.3'), array(array('REMOTE_ADDR' => '127.0.0.1', 'CLIENT_IP' => '127.0.0.2', 'HTTP_X_FORWARDED_FOR' => '127.0.0.4'), '127.0.0.4'), array(array('REMOTE_ADDR' => '127.0.0.1', 'CLIENT_IP' => '127.0.0.2', 'X_FORWARDED_FOR' => '127.0.0.3', 'HTTP_X_FORWARDED_FOR' => '127.0.0.4'), '127.0.0.3'), ); } public function testGetReferrer() { $env = \Slim\Environment::mock(array( 'HTTP_REFERER' => 'http://foo.com' )); $req = new \Slim\Http\Request($env); $this->assertEquals('http://foo.com', $req->getReferrer()); $this->assertEquals('http://foo.com', $req->getReferer()); } public function testGetReferrerWhenNotExists() { $env = \Slim\Environment::mock(); $req = new \Slim\Http\Request($env); $this->assertNull($req->getReferrer()); $this->assertNull($req->getReferer()); } public function testGetUserAgent() { $env = \Slim\Environment::mock(array( 'HTTP_USER_AGENT' => 'user-agent-string' )); $req = new \Slim\Http\Request($env); $this->assertEquals('user-agent-string', $req->getUserAgent()); } public function testGetUserAgentWhenNotExists() { $env = \Slim\Environment::mock(); unset($env['HTTP_USER_AGENT']); $req = new \Slim\Http\Request($env); $this->assertNull($req->getUserAgent()); } } 